import numpy as np, pandas as pd
from scipy.optimize import minimize
d=np.array(pd.read_parquet('equation.parquet').iloc[0]['training_set'].tolist())
y=d[:,0]; P=d[:,2]
def run(s1,s2):
    def eq(p):
        return p[0]*((P**(1/3)+2*P)/s1) + p[1]*(P**2/s2)
    def loss(p): return np.mean((eq(p)-y)**2)
    r=minimize(loss,[1.0]*10,method='BFGS')
    return r.fun, r.nit, r.success
for s1 in [1,50,100,160]:
    for s2 in [1,1000,6000,8000]:
        print(s1,s2,run(s1,s2))
"

